from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG_INF = -10**15

        prev = [[NEG_INF] * 3 for _ in range(n)]

        for i in range(m):
            curr = [[NEG_INF] * 3 for _ in range(n)]

            for j in range(n):
                value = coins[i][j]

                if i == 0 and j == 0:
                    if value >= 0:
                        curr[j][0] = value
                    else:
                        curr[j][0] = value
                        curr[j][1] = 0
                    continue

                for used in range(3):
                    best_prev = NEG_INF

                    if i > 0:
                        best_prev = max(best_prev, prev[j][used])
                    if j > 0:
                        best_prev = max(best_prev, curr[j - 1][used])

                    if best_prev == NEG_INF:
                        continue

                    curr[j][used] = max(curr[j][used], best_prev + value)

                    if value < 0 and used < 2:
                        curr[j][used + 1] = max(curr[j][used + 1], best_prev)

            prev = curr

        return max(prev[n - 1])
